mapper.select:
SELECT 

WHERE d.kind = #{kind}
AND d.doc_no LIKE CONCAT('%', #{q.docNo}, '%')
AND d.biz_type = #{q.bizType}
AND d.io_category = #{q.ioCategory}

AND (d.to_warehouse_id = #{q.warehouseId}
    OR EXISTS (SELECT 1 FROM wms_stock_doc_item wi WHERE wi.doc_id = d.id AND COALESCE(wi.warehouse_id, d.warehouse_id) = #{q.warehouseId}))
AND d.status = #{q.status}
AND d.biz_date >= #{q.beginDate}
AND d.biz_date <= #{q.endDate}
ORDER BY d.id DESC
